SELECT analytics_order_facts.customer_segment, COUNT(DISTINCT analytics_order_facts.active_customer_id) AS active_customer_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2024 AND analytics_order_facts.month = 4 AND analytics_order_facts.region = 'North' AND analytics_order_facts.channel = 'online' GROUP BY analytics_order_facts.customer_segment ORDER BY active_customer_count DESC, analytics_order_facts.customer_segment ASC LIMIT 12
